import {useMemo} from 'react'
import {useRouteQuery, useSuspenseRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {issuesDashboardSurfaceContentRoute} from '../routes/issues-dashboard-surface-content-route'
import type {IssuesDashboardEnrichedDataPayload} from '../types/routes-types'
import type {IssueDeferredItem} from '@github-ui/shared-dashboard-lists/issues/types/list-types'

function toMapById(results: IssueDeferredItem[]) {
  const map = new Map<number, IssueDeferredItem>()
  for (const result of results) map.set(result.id, result)
  return map
}

export function useEnrichedIssues(): IssuesDashboardEnrichedDataPayload {
  const mainQuery = useSuspenseRouteQuery(issuesDashboardSurfaceContentRoute, 'mainQuery')
  const deferredQuery = useRouteQuery(issuesDashboardSurfaceContentRoute, 'deferred')

  const mainResults = mainQuery.data?.results
  const deferredResults = deferredQuery.data?.payload?.issuesDashboardSurfaceContentDeferredData.results

  const enrichedIssuesData = useMemo(() => {
    const deferredById = toMapById(deferredResults || [])
    return mainResults.map(issue => {
      const deferredIssue = deferredById.get(issue.id)
      return {
        ...issue,
        linkedPullRequestCount: deferredIssue?.linkedPullRequestCount,
        subIssuesSummary: deferredIssue?.subIssuesSummary,
        blockedByCount: deferredIssue?.blockedByCount,
      }
    })
  }, [deferredResults, mainResults])

  return {
    issues: enrichedIssuesData,
    pageInfo: mainQuery?.data?.pageInfo,
    isPending: deferredQuery.isPending,
    error: mainQuery.data.error || null,
  }
}
