import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {PullRequestStateIcons} from '@github-ui/issue-pr-state/Icons'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemDescriptionItem} from '@github-ui/list-view/ListItemDescriptionItem'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {useRuntimeEnvironment} from '@github-ui/ssr-utils/use-runtime-environment'
import {useAnalytics} from '@github-ui/use-analytics'
import {CheckCircleFillIcon, CommentIcon, DashIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import {RelativeTime} from '@primer/react'
import React from 'react'
import styles from './PullsInboxSection.module.css'
import unreadStyles from '../shared/UnreadBorder.module.css'
import type {EnrichedPull} from './types/list-types'
import {getCompositeCategoryDisplay, statusCheckColumnDisplay} from './helpers/inbox-helpers'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {PullsChecksStatusBadge} from './PullsChecksStatusBadge'
import {PullsInboxChecksSkeleton} from './PullsInboxSectionSkeletonItem'
import {StackBadge} from '@github-ui/stack-badge'
import {ProfileReference} from '@github-ui/profile-reference'
import {deriveAttributedUsername, isAgentAuthor} from './helpers/derive-attributed-username'

interface PullsInboxListItemProps {
  row: EnrichedPull
  isAgentAttributionEnabled?: boolean
}

// eslint-disable-next-line @typescript-eslint/no-shadow -- named function expression intentionally shares the outer name
export const PullsInboxListItem = React.memo(function PullsInboxListItem({
  row,
  isAgentAttributionEnabled,
}: PullsInboxListItemProps) {
  const {sendAnalyticsEvent} = useAnalytics()
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  const {isBrowser} = useRuntimeEnvironment()

  const PRStateIcon = row.displayState
    ? PullRequestStateIcons[row.displayState as keyof typeof PullRequestStateIcons]
    : undefined
  const [owner, repo] = row.repoNameWithOwner.split('/')
  const hovercardProps = getHovercardAttributesForType('pull_request', {
    owner,
    repo,
    pullRequestNumber: row.number,
  })

  const attributedUsername = isAgentAttributionEnabled ? deriveAttributedUsername(row) : undefined
  const isPullAgentAuthored = isAgentAttributionEnabled ? isAgentAuthor(row) : false

  const display = row.category ? getCompositeCategoryDisplay(row.category, row.statusCheckRollup) : null
  const IconComponent = display?.icon
  const commitChecksDialogEnabled = isBrowser && isFeatureEnabled('pull_request_commit_checks_dialog')

  return (
    <ListItem
      className={clsx(!row.isReadByCurrentUser && unreadStyles.unreadBorder)}
      metadataContainerClassName={styles.metadataContainer}
      title={
        <ListItemTitle
          className="mr-2 color-fg-default"
          value={row.title}
          href={row.permalink}
          onClick={() => sendAnalyticsEvent('inbox.click', 'LIST_ITEM_TITLE', {displayState: row.displayState})}
          linkProps={hovercardProps}
        />
      }
      metadata={[
        <ListItemMetadata key="status" className={styles.statusColumn}>
          {display ? (
            <span className={styles.categoryBadge} data-variant={display.variant}>
              {IconComponent ? (
                <span style={display.iconColor ? {color: display.iconColor} : undefined}>
                  <IconComponent
                    className={styles.statusColumnIcon}
                    size={12}
                    data-testid="status-indicator"
                    aria-label={`${display.label} indicator`}
                  />
                </span>
              ) : display.variant === 'success' ? (
                <CheckCircleFillIcon
                  size={12}
                  className={styles.categoryBadgeSuccessIcon}
                  data-testid="status-indicator"
                  aria-label="Ready to merge indicator"
                />
              ) : (
                <span className={styles.categoryBadgeDot} data-testid="status-indicator" />
              )}
              {display.label}
            </span>
          ) : (
            <span className={clsx('color-fg-muted', styles.emptyPlaceholder)}>&mdash;</span>
          )}
        </ListItemMetadata>,
        <ListItemMetadata key="checks" className={styles.checksColumn}>
          {row.deferredDataStatus === 'pending' ? (
            <PullsInboxChecksSkeleton />
          ) : row.statusCheckRollup ? (
            <span className={styles.statusChecks}>
              {commitChecksDialogEnabled && row.headSha ? (
                <PullsChecksStatusBadge
                  headSha={row.headSha}
                  repositoryNwo={row.repoNameWithOwner}
                  statusCheckRollup={row.statusCheckRollup}
                  aliveChannel={row.commitHeadShaChannel}
                />
              ) : (
                statusCheckColumnDisplay(row.statusCheckRollup)
              )}
            </span>
          ) : (
            <span className={clsx('color-fg-muted', styles.emptyPlaceholder)}>&mdash;</span>
          )}
        </ListItemMetadata>,
        <ListItemMetadata key="comments" className={styles.commentsColumn}>
          {row.commentCount > 0 ? (
            <span className={styles.metadataCell}>
              <CommentIcon size={16} /> {row.commentCount}
            </span>
          ) : (
            <span className={clsx('color-fg-muted', styles.emptyPlaceholder)}>&mdash;</span>
          )}
        </ListItemMetadata>,
      ]}
    >
      <ListItemLeadingContent>
        {!row.isReadByCurrentUser && <span className="sr-only">Unread</span>}
        <ListItemLeadingVisual>
          {PRStateIcon ? (
            <PRStateIcon />
          ) : (
            <DashIcon size={16} className="color-fg-muted" data-testid="fallback-pr-state-icon" />
          )}
        </ListItemLeadingVisual>
      </ListItemLeadingContent>
      <ListItemMainContent>
        <ListItemDescription className={styles.description}>
          <ListItemDescriptionItem>
            {row.repoNameWithOwner}#{row.number} &bull;{' '}
            {attributedUsername && (
              <>
                <ProfileReference login={attributedUsername} profileName={attributedUsername} isAgent={false} />{' '}
                with{' '}
              </>
            )}
            <ProfileReference
              login={row.author.displayLogin}
              profileName={row.author.displayLogin}
              isAgent={isPullAgentAuthored}
            />
            {isBrowser && (
              <>
                {' '}
                &bull; Updated <RelativeTime date={new Date(row.updatedAt)} />
              </>
            )}
          </ListItemDescriptionItem>
          {row.stackPosition != null && row.stackSize != null && (
            <ListItemDescriptionItem>
              <StackBadge
                stackPosition={row.stackPosition}
                stackSize={row.stackSize}
                pullRequestNumber={row.number}
                repoNameWithOwner={row.repoNameWithOwner}
              />
            </ListItemDescriptionItem>
          )}
        </ListItemDescription>
      </ListItemMainContent>
    </ListItem>
  )
})
