import {useMemo} from 'react'
import {queryFnFetch} from '@github-ui/react-core/future/query-fn-fetch'
import {useSuspenseRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useQuery} from '@github-ui/react-query'
import {useSearchParams, useParams} from '@github-ui/react-router'
import {pullsDashboardSurfaceContentRoute} from '../routes/pulls-dashboard-surface-content-route'
import {PULLS_PATH} from '../constants/routes'
import {queryResolver} from '../helpers/query-resolver'
import type {PullsDashboardDeferredDataPayload, PullsDashboardEnrichedDataPayload} from '../types/routes-types'
import type {DeferredItem} from '@github-ui/shared-dashboard-lists/pulls/types/list-types'

const EMPTY_RESULTS: DeferredItem[] = []

function toMapById(results: DeferredItem[]) {
  const map = new Map<number, DeferredItem>()
  for (const result of results) map.set(result.id, result)
  return map
}

export function useEnrichedPulls(): PullsDashboardEnrichedDataPayload {
  const [searchParams] = useSearchParams()
  const {mode} = useParams<{mode?: string}>()
  const mainQuery = useSuspenseRouteQuery(pullsDashboardSurfaceContentRoute, 'mainQuery')

  const mainResults = mainQuery.data?.results ?? EMPTY_RESULTS
  const deferredQueryDeps = useMemo(() => {
    const q = queryResolver({searchParams, params: {mode}})
    const nextSearchParams: Array<[string, string]> = [
      ['q', q],
      ['page', searchParams.get('page') || '1'],
    ]

    for (const pull of mainResults) {
      nextSearchParams.push(['pr_ids[]', String(pull.id)])
    }

    return {
      pathname: `${PULLS_PATH}/deferred`,
      searchParams: nextSearchParams,
    }
  }, [mainResults, mode, searchParams])

  const deferredQueryKey = useMemo(
    () => ['dashboard-surface', 'pulls', 'deferredEnrichedPulls', deferredQueryDeps],
    [deferredQueryDeps],
  )

  // eslint-disable-next-line @github-ui/github-monorepo/require-query-persister -- depends on in-memory main query results (pr_ids)
  const deferredQuery = useQuery({
    queryKey: deferredQueryKey,
    queryFn: ({signal}) => {
      return queryFnFetch<PullsDashboardDeferredDataPayload>({
        queryDeps: {
          ...deferredQueryDeps,
          init: {signal},
        },
      })
    },
    enabled: mainResults.length > 0,
  })

  const deferredResults = deferredQuery.data?.payload?.pullsDashboardSurfaceContentDeferredData.results

  const enrichedPullsData = useMemo(() => {
    const deferredById = toMapById(deferredResults || [])
    return mainResults.map(pull => {
      const deferredPull = deferredById.get(pull.id)
      return {
        ...pull,
        reviewDecisionState: deferredPull?.reviewDecisionState,
        statusCheckRollup: deferredPull?.statusCheckRollup,
      }
    })
  }, [deferredResults, mainResults])

  return {
    pulls: enrichedPullsData,
    pageInfo: mainQuery?.data?.pageInfo,
    isPending: deferredQuery.isPending,
    // mainQuery is blocking so the request cannot have failed; no need to check `isError`
    error: mainQuery.data.error || null,
  }
}
