import {verifiedFetch} from '@github-ui/verified-fetch'
import {useAnalytics} from '@github-ui/use-analytics'
import {useRef} from 'react'

import {DisplayMode} from '@github-ui/shared-dashboard-lists/shared/types/list-types'

/**
 * Hook to manage and persist the compact mode setting for lists.
 * @param compactMode The initial compact mode value.
 * @param preferenceKey The key to use for the FormData.
 */
export function useUpdateCompactModeSetting(compactMode: boolean, preferenceKey: string) {
  const savedCompactModeRef = useRef(compactMode)

  const {sendAnalyticsEvent} = useAnalytics()

  async function updateCompactModeSetting(value: boolean) {
    if (savedCompactModeRef.current === value) {
      return
    }

    sendAnalyticsEvent('pull-requests.click', 'DENSITY_TOGGLE', {
      density: value ? DisplayMode.Compact : DisplayMode.Default,
    })

    savedCompactModeRef.current = value

    const formData = new FormData()
    formData.set(preferenceKey, value.toString())
    await verifiedFetch('/pulls/preferences', {method: 'PUT', body: formData})
  }

  return {updateCompactModeSetting}
}
