import {ListView} from '@github-ui/list-view'
import {clsx} from 'clsx'

import styles from './PullsInboxSection.module.css'
import {PullsInboxSectionSkeletonItem} from './PullsInboxSectionSkeletonItem'

interface DashboardSectionSkeletonProps {
  name: string
  numItems: number
}

export function PullsDashboardInboxSectionSkeleton({name, numItems}: DashboardSectionSkeletonProps) {
  const titleId = `pulls-inbox-skeleton-${name.toLowerCase().replace(/\s+/g, '-')}`

  return (
    <section aria-label={`Loading ${name}`} data-testid="pulls-inbox-section-skeleton">
      <h2 id={titleId} className="h4">
        {name}
      </h2>
      <div className={clsx(styles.listContainer, 'border border-color-muted rounded-2')}>
        <ListView title={name} titleHeaderTag="h2" ariaLabelledBy={titleId}>
          {Array.from({length: numItems}, (_, i) => (
            <PullsInboxSectionSkeletonItem key={i} />
          ))}
        </ListView>
      </div>
    </section>
  )
}
