import {getCookie, setCookie} from '@github-ui/cookies'
import {useCallback, useState} from 'react'

const COOKIE_NAME = 'dashboard_surface_collapsed_sections'
const COOKIE_EXPIRY_MS = 30 * 24 * 60 * 60 * 1000

let collapsedIds: Set<string> | null = null

function getCollapsedIds(): Set<string> {
  if (collapsedIds === null) {
    const raw = getCookie(COOKIE_NAME)?.value ?? ''
    collapsedIds = new Set(
      raw
        .split(',')
        .map(s => s.trim())
        .filter(Boolean),
    )
  }
  return collapsedIds
}

function writeCollapsedIds(ids: Set<string>) {
  collapsedIds = ids
  const expireTime = new Date(Date.now() + COOKIE_EXPIRY_MS).toUTCString()
  setCookie(COOKIE_NAME, [...ids].join(','), expireTime)
}

/**
 * Hook to manage the collapsed state of an inbox section.
 * Reads the current state from the browser cookie on mount (the single source of truth),
 * and writes back to the cookie on every toggle.
 *
 * @param sectionId The inbox section ID (e.g. 'review-requested').
 * @param initialCollapsed Optional server-provided fallback used for the first render so
 * the server and client can agree before browser cookies are available.
 */
export function useSaveCollapsedSection(sectionId: string, initialCollapsed = false) {
  const [isCollapsed, setIsCollapsed] = useState(() => {
    if (typeof document !== 'undefined') {
      return getCollapsedIds().has(sectionId)
    }
    return initialCollapsed
  })

  const setCollapsed = useCallback(
    (collapsed: boolean) => {
      setIsCollapsed(collapsed)

      const ids = new Set(getCollapsedIds())
      if (collapsed) {
        ids.add(sectionId)
      } else {
        ids.delete(sectionId)
      }
      writeCollapsedIds(ids)
    },
    [sectionId],
  )

  return {isCollapsed, setCollapsed}
}
